BEGIN;

-- 2026年版 Professional Cloud DevOps Engineer 試験ガイドのAI関連項目(Gemini Code/Cloud Assist、
-- Gemini CLI、MLワークロードのCI/CD、Active Assist)を、gcp-pcde に続き
-- 残り4セット(c/d/e/g)にも別角度・別シナリオで展開する。

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('gcp-pcde-c-q51', '組織のブートストラップと維持',
   '同じようなgcloudコマンドの組み合わせを毎日繰り返し打っている。この反復作業への対処として、Gemini CLIの適切な位置づけはどれか。',
   NULL::text,
   '["ターミナル上で自然言語の指示からgcloudコマンド列を組み立てさせて反復作業を減らす。定型化が進んだ部分をスクリプト化するかは引き続き人が判断する。","Gemini CLIを導入すれば、Python/Goによる自動化スクリプトの作成そのものが不要になり、以後は一切スクリプトを書かなくてよいと位置づける。","Gemini CLIはConsole画面の操作を代行する機能であり、ターミナルからの利用はできないため導入しても意味が無いと案内する。","反復作業の効率化はCloud Schedulerの導入だけで十分であり、AI支援ツールをあえて追加する必要は無いと判断する。"]',
   0, '[0]', 'single',
   '{"asked":"Gemini CLIによるターミナル作業の自動化支援の位置づけを理解しているか。","why_asked":"試験ガイドは開発・運用支援AIの例としてGemini CLIを名指ししている。試験は『AIがあれば手書きスクリプトは要らない』という飛躍と、『CLIはターミナル向けではない』という誤解の両方を誤答に置き、AIは反復作業の負担を下げる道具であって判断主体ではないことを測る。","kid":"自然言語でコマンドを組み立ててもらい、繰り返しの手間を減らす。スクリプト化するかは人が決める。","terms":[["Gemini CLI","ターミナルから自然言語でGoogle Cloudの操作を支援するAIエージェント。"]],"think":"反復コマンドを毎回手で組み立てる手間をAIに肩代わりさせ、さらに定型化できる部分は通常のスクリプトへ引き継ぐ、という段階的な効率化で考える。","vs":"『スクリプトが不要になる』『ターミナルでは使えない』はどちらもGemini CLIの実際の使いどころを取り違えている。","opt":["正解。自然言語からコマンド列を組み立てさせ、スクリプト化の判断は人が引き続き担う。","Gemini CLIはコマンド組み立てを支援するが、再現性の高い自動化にはスクリプト化が引き続き有効であり、不要にはならない。","Gemini CLIはターミナルから使うAIエージェントであり、Console操作の代行に限定されない。","Cloud Schedulerは定期実行の仕組みであり、コマンド自体を組み立てる支援にはならない。両方を組み合わせる余地がある。"]}'),

  ('gcp-pcde-c-q52', 'CI/CDパイプラインの構築と実装',
   '機械学習モデルの新バージョンをカナリアデプロイしている。ロールアウトを本採用に進めるかどうかを判断する基準として適切なものはどれか。',
   NULL::text,
   '["推論のレイテンシやエラー率に加えて、モデルの予測精度など機械学習パイプライン固有のテレメトリも成功指標に含めて判定する。","アプリケーションの一般的な成功指標(レイテンシとエラー率)だけで判定し、モデルの予測精度は判定基準に含めない。","カナリア期間中はモデルの出力を監視せず、期間が終わったタイミングでまとめて精度を確認する。","新バージョンのモデルはロールバックが難しいため、カナリア自体を行わず全トラフィックへ一括で切り替える。"]',
   0, '[0]', 'single',
   '{"asked":"MLパイプライン特有のテレメトリを成功指標に含めたカナリア判定を理解しているか。","why_asked":"試験ガイドはデプロイ戦略の成功指標を『application or ML pipeline telemetry』と明記した。試験はアプリの一般的な指標だけでMLモデルの良し悪しを判定できると錯覚させる誤答を置き、モデル固有の精度指標が必要なことを測る。","kid":"レイテンシやエラー率だけでなく、モデルの当たり外れ(精度)も見てから本採用を決める。","terms":[["カナリアデプロイ","新バージョンを一部のトラフィックにだけ流し、問題が無いか確認しながら段階的に広げる手法。"]],"think":"モデルはレイテンシやエラー率が正常でも、予測精度だけが劣化することがある。だから一般的な指標に加えて、モデル固有のテレメトリも判定基準に加える必要がある。","vs":"『アプリの指標だけで十分』はモデル劣化を見逃す。『監視せず後でまとめて確認』『カナリアをしない』はどちらも段階的検証という発想自体を放棄している。","opt":["正解。一般的な成功指標に加えて、モデル固有のテレメトリ(予測精度など)も判定基準に含める。","レイテンシとエラー率が正常でも予測精度だけが劣化することがあり、それを見逃してしまう。","監視を後回しにすると、劣化したモデルへ長時間トラフィックを流し続けるリスクを負う。","一括切り替えはロールバックの難しさへの対処になっておらず、むしろ問題発生時の影響範囲を広げる。"]}'),

  ('gcp-pcde-c-q53', 'オブザーバビリティの実践',
   'Logging クエリ言語(LQL)に不慣れなメンバーが、特定条件のログを絞り込みたいが構文が書けず困っている。Gemini Cloud Assistの使い方として適切なものはどれか。',
   NULL::text,
   '["絞り込みたい条件を自然言語で伝えてLQLのクエリ案を生成させ、その内容を確認・調整してからLogs Explorerで実行する。","LQLを書けないメンバーはログの絞り込み自体を諦め、全件のログを目視で確認する運用にする。","Gemini Cloud AssistはLQLの構文生成には対応しておらず、あらかじめLQLを習得したメンバーしか使えない。","AIが生成したクエリはそのまま実行結果を信頼してよく、内容の確認は不要とする。"]',
   0, '[0]', 'single',
   '{"asked":"LQL不慣れなメンバーへのGemini Cloud Assist活用(クエリ生成支援)を理解しているか。","why_asked":"試験ガイドはログ分析のAI活用を明記しており、クエリ言語の習熟度に関わらず活用できる点が実務上の価値になる。試験は『AIはLQL習熟者専用』という誤解と、『生成結果を無条件に信頼してよい』という過信の両方を誤答に置く。","kid":"やりたいことを言葉で伝えてクエリ案を作ってもらい、中身を確認してから使う。","terms":[["Logging クエリ言語(LQL)","Cloud Loggingでログを絞り込むための検索構文。"]],"think":"構文を覚える手間をAIに肩代わりさせつつ、生成された内容が意図通りかは人が確認する、という分業で考える。","vs":"『諦めて全件確認』は非効率、『習得者専用』は機能の価値を見誤り、『無条件に信頼』は確認という工程を省いている。","opt":["正解。自然言語で条件を伝えてクエリ案を生成させ、確認してから実行するのが適切な使い方。","全件を目視で確認するのは非効率であり、AI支援によってクエリ作成の障壁を下げられることを見落としている。","Gemini Cloud AssistはLQLに不慣れなメンバーでもクエリ案の生成を支援でき、習熟者専用ではない。","生成されたクエリが意図通りかは人が確認すべきであり、無条件に信頼すると意図しないログまで含めてしまうことがある。"]}'),

  ('gcp-pcde-c-q54', 'パフォーマンス最適化とトラブルシューティング',
   'GKEクラスタとCompute Engineインスタンスの両方で、実際の使用率に対してリソースを過剰に確保している疑いがある。まず何を確認するべきか。',
   NULL::text,
   '["Active Assistが提示するライトサイジングの推奨事項を確認し、使用率の実績に基づいた縮小案を参考に調整する。","全インスタンスとノードプールを停止し、使用率のログが十分に溜まるまで新規作成を控える。","ライトサイジングはCompute Engineにのみ提供される機能であり、GKEのノードには推奨事項が出ないと判断する。","推測でリソースを一律半分に縮小し、問題が起きたら都度戻す運用にする。"]',
   0, '[0]', 'single',
   '{"asked":"Active Assistのライトサイジング推奨事項を、過剰確保の調査の起点として使えるか理解しているか。","why_asked":"試験ガイドはパフォーマンス情報収集の項目にActive Assistのインサイトと推奨事項を明記している。試験は『対象がCompute Engineに限られる』という誤解や、『推測で一律縮小する』という乱暴な対処を誤答に置き、実績データに基づく推奨事項の確認が先であることを測る。","kid":"実際の使用率をもとにした縮小案をAIがすでに出しているので、まずそれを見る。","terms":[["ライトサイジング","実際の使用率に見合った適切なサイズへリソースを調整すること。"]],"think":"推測で調整すると過小/過剰のどちらにも振れうる。使用率の実績データに基づく推奨事項を先に確認してから調整する方が、根拠のある判断になる。","vs":"全停止は可用性を犠牲にし、Compute Engine限定という認識は対象範囲を狭く見誤り、一律縮小は実績データを無視した乱暴な対処。","opt":["正解。使用率の実績に基づく推奨事項をまず確認し、それを参考に調整する。","全停止は可用性への影響が大きく、使用率データを集めるためだけに取る手段として釣り合わない。","Active AssistのライトサイジングはGKEのノードプールも対象に含まれ、Compute Engine限定ではない。","一律縮小は実際の使用率を無視しており、必要なリソースまで削ってしまう可能性がある。"]}'),

  ('gcp-pcde-d-q51', '組織のブートストラップと維持',
   '全チームが使うCloud Workstationsのカスタムイメージを整備している。開発体験を底上げする観点で、Gemini Code Assistをどう扱うのが適切か。',
   NULL::text,
   '["IDE拡張としてGemini Code Assistをあらかじめカスタムイメージへ組み込み、開発者が個別にセットアップしなくても使える状態にしておく。","Gemini Code Assistは個人のライセンス契約が前提のため、カスタムイメージへの組み込みはできないと案内する。","コード補完AIはチームごとに好みが分かれるため、カスタムイメージには一切のAIツールを含めない方針にする。","Gemini Code Assistをイメージに含めると起動のたびに認証が必要になり、CI/CDのビルド時間を著しく圧迫すると判断してイメージからは外す。"]',
   0, '[0]', 'single',
   '{"asked":"Cloud Workstationsのブートストラップ(カスタムイメージ)にAI支援ツールを組み込む発想を理解しているか。","why_asked":"試験ガイドは開発環境のブートストラップ(カスタムイメージ、IDE、Cloud SDK)とAI支援の活用を並べて記載している。試験は個別セットアップに任せる非効率と、AI活用そのものを避ける消極策の両方を誤答に置き、イメージへの事前組み込みという発想を測る。","kid":"最初からIDEにAI支援を入れた状態のイメージを配って、みんながすぐ使えるようにする。","terms":[["カスタムイメージ","必要なツールをあらかじめ組み込んだ、開発環境の雛形となるイメージ。"]],"think":"開発者ごとに個別セットアップさせると、ばらつきと手間が生まれる。あらかじめイメージへ組み込んでおけば、誰もが同じ開発体験からスタートできる。","vs":"『ライセンス上組み込めない』『チームの好みでAIを外す』『ビルド時間を理由に外す』はいずれも根拠のない、または的外れな懸念で、事前組み込みという選択肢そのものを退けている。","opt":["正解。カスタムイメージへ組み込んでおけば、開発者が個別にセットアップする手間を省ける。","組み込み可否はライセンス形態次第であり、個人契約前提だから組み込めないと一律に決めつけるのは誤り。","好みが分かれることと、選択肢として使えるようにしておくことは別の話であり、最初から排除する理由にはならない。","IDE拡張の組み込みは実行時の起動処理であり、CI/CDのビルド時間そのものを圧迫する要因ではない。"]}'),

  ('gcp-pcde-d-q52', 'CI/CDパイプラインの構築と実装',
   '機械学習モデルの複数バージョンを本番へ順次デプロイしている。モデルのアーティファクト管理として適切なものはどれか。',
   NULL::text,
   '["学習済みモデルをバージョン管理された成果物としてArtifact Registryへ登録し、どのバージョンがいつ本番へデプロイされたか追跡できるようにする。","モデルファイルは容量が大きいことを理由に、バージョン管理は行わず最新版のみを共有ストレージへ都度上書き保存する運用にする。","モデルのバージョン管理はコードの管理と重複するとみなし、Gitリポジトリでの管理だけに一本化してモデル自体は管理対象から外してしまう。","デプロイ済みのモデルがどのバージョンかは、推論結果の傾向から都度推測して判断する、記録に頼らない運用にする。"]',
   0, '[0]', 'single',
   '{"asked":"MLモデルをバージョン管理された成果物として扱うアーティファクト管理の考え方を理解しているか。","why_asked":"試験ガイドはArtifact Registryによるアーティファクト管理と、CI/CD対象への機械学習ワークロードの追加を並べて記載している。試験はモデルを『特別扱いして管理対象から外す』発想を誤答に置き、モデルもアプリのアーティファクトと同様に追跡可能であるべきだと測る。","kid":"学習済みモデルもバージョンを付けて保管し、どれがいつ本番に出ているか追えるようにする。","terms":[["アーティファクト管理","ビルド成果物をバージョン管理し、由来やデプロイ履歴を追跡できるようにする仕組み。"]],"think":"上書き保存や推測に頼ると、問題発生時にどのバージョンが原因か切り分けられない。バージョンごとに登録し追跡できる状態にしておくことで、原因調査やロールバックが可能になる。","vs":"『上書き保存』『管理対象から外す』『推測で判断』はいずれも追跡可能性を放棄しており、障害時の切り分けを困難にする。","opt":["正解。バージョン管理された成果物として登録し、デプロイ履歴を追跡できるようにする。","上書き保存では過去のバージョンが失われ、問題発生時にどのバージョンが原因か切り分けられなくなる。","コードとモデルは別の成果物であり、コードのバージョン管理だけではモデル自体の追跡ができない。","推測に頼る運用は不確実であり、明示的なバージョン管理があれば不要な手間である。"]}'),

  ('gcp-pcde-d-q53', 'オブザーバビリティの実践',
   'Google Cloud Managed Service for Prometheusのダッシュボードを新しく作りたいが、PromQLのクエリをゼロから書くのに時間がかかっている。Gemini Cloud Assistの適切な活用方法はどれか。',
   NULL::text,
   '["見たいグラフの内容を自然言語で伝えてPromQLクエリの下書きを生成させ、意図通りの集計になっているかを確認してからダッシュボードへ組み込む。","PromQLはGemini Cloud Assistの対象外のクエリ言語であり、Cloud Monitoringのクエリ言語にしか対応していないと案内する。","生成されたPromQLクエリはそのままダッシュボードへ組み込み、集計結果の確認は運用が始まってから行う。","クエリ作成に時間がかかることを理由に、ダッシュボード自体を作らず生データを都度目視で確認する運用にする。"]',
   0, '[0]', 'single',
   '{"asked":"Gemini Cloud Assistによるメトリクス関連クエリ(PromQL含む)の下書き支援を理解しているか。","why_asked":"試験ガイドはメトリクス解釈へのGemini Cloud Assist活用とPromQLによるダッシュボード管理を並べて記載している。試験は対応クエリ言語を限定的に誤解させる誤答と、生成結果を無検証で使う誤答を置き、下書き生成後の確認という工程を測る。","kid":"見たいグラフを言葉で伝えてクエリの下書きを作ってもらい、意図通りか確かめてから使う。","terms":[["PromQL","Prometheus形式のメトリクスを集計・可視化するためのクエリ言語。"]],"think":"クエリ構文を覚える手間をAIに肩代わりさせつつ、集計の意図とずれていないかは人が確認する、という分業で考える。","vs":"『PromQLは対象外』は誤り、『無検証で組み込む』『作成自体を諦める』はどちらも確認や効率化という工程を放棄している。","opt":["正解。自然言語で内容を伝えてPromQLの下書きを生成させ、確認してから組み込む。","Gemini Cloud AssistはPromQLを含むメトリクスクエリの下書き生成を支援でき、対象外ではない。","生成されたクエリが意図通りの集計かは事前に確認すべきであり、無検証での組み込みは誤った可視化につながる。","ダッシュボード化を諦めると継続的な監視ができなくなり、都度の目視確認は見落としのリスクを抱える。"]}'),

  ('gcp-pcde-d-q54', 'オブザーバビリティの実践',
   '特定のリクエストで発生したエラーについて、分散トレースと構造化ログを突き合わせて原因を調べたい。Gemini Cloud Assistをこの相関付け作業でどう使うのが適切か。',
   NULL::text,
   '["対象のトレースIDを渡して関連する構造化ログの要点をAIに整理させ、トレースのどのスパンとログのどの行が対応するかの見当をつけた上で、人が詳細を確認する。","トレースIDとログの相関付けはGemini Cloud Assistの対象外であり、手作業でログを1行ずつ検索するしかないと案内する。","AIが提示した対応関係をそのまま最終的な原因説明として採用し、ログの中身自体は確認しない。","相関付けが手間であることを理由に、今後はトレースIDをログへ含めない設計に変更する。"]',
   0, '[0]', 'single',
   '{"asked":"Gemini Cloud Assistによるトレースとログの相関付け支援の使いどころを理解しているか。","why_asked":"試験ガイドはトレースIDと構造化ログの相関付け、およびAIによるトレース分析支援を並べて記載している。試験は『AIは対象外』という過小評価と、『AIの結果をそのまま採用』という過信の両方を誤答に置き、見当をつける支援として使う位置づけを測る。","kid":"AIにトレースとログの対応関係を整理してもらい、そこから先の詳しい確認は人がする。","terms":[["トレースID","1つのリクエストに紐づく識別子。トレースとログを結びつける鍵になる。"]],"think":"手作業での突き合わせは時間がかかる。AIに対応関係の見当をつけさせ、絞り込んだ範囲を人が詳しく確認する、という分業で考える。","vs":"『対象外』は機能を過小評価し、『そのまま採用』は確認という工程を省いており、『トレースIDを外す』はそもそも相関付けの手段自体を放棄している。","opt":["正解。AIに対応関係の見当をつけさせ、そこから人が詳細を確認するのが適切な使い方。","Gemini Cloud Assistはトレースとログの相関付けの整理を支援でき、手作業のみが唯一の手段ではない。","AIが提示する対応関係は見当であり、ログの中身を確認せずに最終的な原因説明として採用するのは早計。","トレースIDを外すと相関付けの手がかり自体を失い、原因調査がかえって難しくなる。"]}'),

  ('gcp-pcde-e-q51', '組織のブートストラップと維持',
   '新しいTerraformモジュールを書く際、構文を毎回調べながら書くのに時間がかかっている。Gemini Code Assistの活用として適切なものはどれか。',
   NULL::text,
   '["実現したい構成を自然言語やコメントで伝えてTerraformコードの下書きを生成させ、生成された内容をレビューしてから適用する。","Gemini Code AssistはHCL(Terraformの構文)には対応しておらず、汎用プログラミング言語のコード補完にのみ使える。","生成されたTerraformコードはレビューを省略してそのままapplyし、問題が起きたら都度直す運用にする。","Terraformの構文習得を避けるため、以後はコンソールでの手作業構築に切り替える。"]',
   0, '[0]', 'single',
   '{"asked":"Gemini Code AssistによるIaCコード生成支援の位置づけを理解しているか。","why_asked":"試験ガイドは開発運用支援AIの活用と、TerraformなどのIaCツーリングを別項目としながら並べて記載している。試験は対応言語を限定的に誤解させる誤答と、レビューを省略する誤答を置き、生成後のレビューという工程を測る。","kid":"作りたい構成を言葉で伝えてTerraformの下書きを書いてもらい、中身を確認してから適用する。","terms":[["HCL","Terraformの設定ファイルを書くための構文。"]],"think":"構文を都度調べる手間をAIに肩代わりさせつつ、生成内容が意図通りかは人がレビューしてから適用する、という分業で考える。","vs":"『HCLには対応しない』は誤り、『レビュー省略』『手作業へ切り替え』はどちらもIaCの利点(再現性・レビュー可能性)を手放している。","opt":["正解。自然言語で構成を伝えて下書きを生成させ、レビューしてから適用する。","Gemini Code AssistはHCLを含む幅広い言語のコード生成を支援でき、汎用言語限定ではない。","レビューを省略すると、意図しない構成のまま本番へ適用してしまうリスクを負う。","手作業構築は再現性が無く、Terraformで得られるレビュー可能性や履歴管理を手放すことになる。"]}'),

  ('gcp-pcde-e-q52', 'オブザーバビリティの実践',
   '個人情報を含む可能性があるログについて、Gemini Cloud Assistでの分析支援を使いたい。PII(個人を特定できる情報)の扱いとして適切なものはどれか。',
   NULL::text,
   '["ログプロセッサなどでPIIを事前にredaction(削除・マスキング)した上で、マスキング後のログに対してGemini Cloud Assistの分析支援を利用する。","Gemini Cloud Assistを使えばPIIのマスキング自体が自動的に不要になるため、redactionの設定は省略してよいと位置づける。","PIIを含むログはAI分析の対象から一律除外し、以後そのログ種別についてはあらゆる分析を一切行わない方針にする。","PIIのマスキングはログのエクスポート時にのみ必要であり、Gemini Cloud Assistでの分析時には考慮しなくてよいとする。"]',
   0, '[0]', 'single',
   '{"asked":"PIIの取り扱い(redaction)とGemini Cloud Assistによるログ分析支援の役割分担を理解しているか。","why_asked":"試験ガイドはPII/PHIのredactionと、AIによるログ分析支援を同じログ管理の項目に並べて記載している。試験は『AIがあればマスキングが不要になる』という誤解と、『PII混入ログは分析自体を諦める』という過剰反応の両方を誤答に置き、マスキングを前提としたAI活用という順序を測る。","kid":"個人情報を隠してから、AIに分析を手伝ってもらう。隠す作業自体はAIの役目ではない。","terms":[["PII","個人を特定できる情報。氏名・メールアドレスなど。"],["redaction","ログ中の機微情報を削除・マスキングする処理。"]],"think":"AIによる分析支援とPIIの保護は別レイヤーの対策であり、片方が他方を代替しない。マスキングを済ませた上で分析支援を使う、という順序で考える。","vs":"『マスキング不要』はredactionの役割を軽視し、『分析自体を諦める』『エクスポート時のみ考慮』はどちらも保護と活用のどちらかに偏っている。","opt":["正解。redactionを済ませた上で、マスキング後のログに対してAI分析支援を使う。","AI分析支援の有無に関わらず、PIIの保護はredactionという別の仕組みで担う必要がある。","一律除外すると、そのログ種別から得られる知見自体を失ってしまう。redactionを挟めば分析は可能。","分析時に生ログを扱うのであれば、エクスポート時と同様にPIIへの配慮が必要になる。"]}'),

  ('gcp-pcde-e-q53', 'オブザーバビリティの実践',
   '新しいSLIに対するアラートの閾値をどう設定すればよいか判断材料が足りない。Gemini Cloud Assistをこの場面でどう使うのが適切か。',
   NULL::text,
   '["過去のメトリクスの傾向について自然言語で相談し、閾値の候補についてアドバイスを得た上で、最終的な閾値はSLOやビジネス影響を踏まえて人が決定する。","Gemini Cloud Assistが提示した閾値をそのまま採用し、SLOとの整合性は後から確認すればよいとする。","閾値設定はAIの支援対象外であり、担当者の経験と勘のみに基づいて決定する方針にする。","閾値が決まらないことを理由に、当面はアラートポリシー自体を設定しない運用にする。"]',
   0, '[0]', 'single',
   '{"asked":"アラート閾値設定におけるGemini Cloud Assistの活用範囲(助言と最終判断の分離)を理解しているか。","why_asked":"試験ガイドはアラートポリシー設定とメトリクス解釈へのAI活用を近接した項目として記載している。試験は『AIの提示値をそのまま採用』という過信と、『AIは対象外』という過小評価の両方を誤答に置き、助言を踏まえて人がSLOと突き合わせて決めるという流れを測る。","kid":"AIに傾向を聞いて候補をもらい、最終的な数字はSLOと相談しながら人が決める。","terms":[["SLI","サービスレベル指標。実際に計測する値。"],["アラートポリシー","閾値を超えたときに通知する設定。"]],"think":"過去の傾向をAIに素早く整理させることで検討の出発点を作りつつ、最終的な閾値はビジネス上の許容範囲(SLO)と突き合わせて人が決める、という役割分担で考える。","vs":"『AI提示値をそのまま採用』はSLOとの整合確認を省き、『AIは対象外』『設定自体をしない』はどちらも判断材料や保護の仕組みを放棄している。","opt":["正解。AIから傾向を踏まえた候補を得た上で、最終判断はSLOやビジネス影響を踏まえて人が行う。","AIの提示値がSLOと整合しているとは限らず、確認前に採用すると不適切な閾値のまま運用してしまう。","傾向の整理にAIを活用でき、経験と勘のみに頼る必要はない。","アラート未設定のままでは異常の検知が遅れ、問題を放置するリスクを負う。"]}'),

  ('gcp-pcde-e-q54', 'パフォーマンス最適化とトラブルシューティング',
   '毎月の Compute Engine 利用料を見直し、割引の適用漏れがないか確認したい。まず何を確認するのが効率的か。',
   NULL::text,
   '["Active Assistが提示するコスト関連の推奨事項を確認し、利用実績に基づいたコミット利用割引(CUD)の適用候補を参考にする。","全ワークロードの利用履歴を1件ずつ手作業で洗い出し、割引適用の可否をそれぞれ個別に時間をかけて計算する。","コミット利用割引はGoogle側が自動で全ワークロードへ適用する仕組みのため、確認や設定は一切不要と判断する。","コスト削減のためにまず稼働中のワークロードを停止し、利用実績が十分に減ってから見直しを行う運用にする。"]',
   0, '[0]', 'single',
   '{"asked":"コスト推奨事項(コミット利用割引の候補提示)をFinOpsの起点として使えるか理解しているか。","why_asked":"試験ガイドはGoogle Cloudのコスト系レコメンダーと、Active Assistのインサイト・推奨事項を近接した項目として記載している。試験は『すべて自動適用される』という誤解と、手作業での洗い出しという非効率な対処の両方を誤答に置き、推奨事項の確認を起点にする流れを測る。","kid":"利用実績をもとにした割引の候補をAIがすでに出しているので、まずそれを見る。","terms":[["コミット利用割引(CUD)","一定期間の利用を約束することで単価が下がる割引。"]],"think":"利用実績を人力で洗い出すのは時間がかかる。実績データに基づく推奨事項を先に確認し、そこから適用を検討する方が効率的。","vs":"『自動で全て適用される』は実際には利用実績に応じた選択・申込が必要な場合があることを見落としており、『手作業での洗い出し』『停止してから見直し』はどちらも非効率か本末転倒。","opt":["正解。利用実績に基づく推奨事項をまず確認し、それを参考にコミット利用割引の適用を検討する。","手作業での洗い出しは時間がかかり、既に用意されている推奨事項を活用する方が効率的。","コミット利用割引は利用実績に応じた適用検討が必要な場合があり、確認や設定が一切不要とは限らない。","ワークロードの停止はコスト削減の目的とは別の話であり、利用実績を減らすために稼働を止めるのは本末転倒。"]}'),

  ('gcp-pcde-g-q51', '組織のブートストラップと維持',
   'Google Cloudとオンプレミス環境の両方にまたがる運用作業で、繰り返し発生する調査作業をGemini CLIで効率化したい。適切な位置づけはどれか。',
   NULL::text,
   '["Google Cloud側の調査作業について自然言語で指示しコマンド組み立てを支援させつつ、オンプレミス側の操作はGemini CLIの対象外として別の手段で行う。","Gemini CLIはGoogle Cloudとオンプレミスの両方の操作を単一の自然言語指示で横断的に自動実行できるため、境界を意識せず使ってよい。","ハイブリッド環境ではGemini CLIは一切利用できないため、すべての調査作業を手作業で行う。","Gemini CLIの利用はGKEクラスタの操作のみに限定されており、他のGoogle Cloudサービスの調査には使えない。"]',
   0, '[0]', 'single',
   '{"asked":"ハイブリッド/マルチクラウド環境におけるGemini CLIの対象範囲を理解しているか。","why_asked":"試験ガイドはハイブリッド/マルチクラウド環境の運用と、開発運用支援AIの活用を別項目としながら試験全体で重視している。試験は『AIが環境の境界を越えて何でもできる』という過信と、『ハイブリッドでは使えない』という過小評価の両方を誤答に置き、Google Cloud側の作業を支援する道具という現実的な範囲を測る。","kid":"Google Cloud側の調査はAIに手伝ってもらえるが、オンプレ側は対象外なので別の方法でやる。","terms":[["Gemini CLI","ターミナルから自然言語でGoogle Cloudの操作を支援するAIエージェント。"]],"think":"Gemini CLIが直接操作できるのはGoogle Cloudのリソースであり、オンプレミス側の機器やシステムはその対象に含まれない。この境界を踏まえて、使える範囲と使えない範囲を分けて考える。","vs":"『境界を意識せず横断利用できる』は過信、『ハイブリッドでは使えない』『GKE限定』はどちらも実際の対象範囲を狭く見誤っている。","opt":["正解。Google Cloud側の作業を支援させ、オンプレミス側は対象外として別の手段を使う。","Gemini CLIが直接操作できるのはGoogle Cloud側のリソースであり、オンプレミス側までは自動実行できない。","ハイブリッド環境でも、Google Cloud側の調査作業についてはGemini CLIを活用できる。","Gemini CLIはGKEに限らず、Google Cloudの幅広いサービスに関する調査作業を支援できる。"]}'),

  ('gcp-pcde-g-q52', 'CI/CDパイプラインの構築と実装',
   'アプリケーションのコード変更でパイプラインが動く一般的なCI/CDに加えて、機械学習モデルの再学習パイプラインのトリガーを設計している。適切な考え方はどれか。',
   NULL::text,
   '["コード変更によるトリガーとは別に、新しい学習データの到着やモデル精度の劣化検知などモデル固有の条件でも再学習パイプラインが起動するようトリガーを設計する。","モデルの再学習もコードの一部として扱い、コード変更以外のトリガーは設計せず、コードの変更が無い限り再学習は一切行わない運用にする。","再学習パイプラインは一度組んだら固定のトリガー条件を変更する必要はなく、運用開始後の見直しは不要とする。","モデル精度の劣化検知は運用チームの目視確認に任せ、パイプラインのトリガーとしては組み込まない。"]',
   0, '[0]', 'single',
   '{"asked":"MLワークロード特有のパイプライントリガー(データ到着・精度劣化検知)の設計を理解しているか。","why_asked":"試験ガイドはCI/CDパイプライントリガーの設計と、機械学習ワークロードのCI/CDを並べて記載している。試験は『コード変更トリガーだけで十分』という一般CI/CD発想の持ち込みを誤答に置き、モデル固有のトリガー条件が必要になることを測る。","kid":"コードが変わった時だけでなく、新しいデータが来た時やモデルの精度が落ちた時にも再学習が始まるようにする。","terms":[["再学習パイプライン","新しいデータや劣化検知をきっかけにモデルを学習し直す一連の処理。"]],"think":"モデルの劣化はコード変更が無くても、データの分布変化などによって起きる。だからコード変更トリガーとは別に、データ到着や精度劣化検知をトリガーとして設計する必要がある。","vs":"『コード変更のみをトリガーにする』は一般的なCI/CDの発想をそのまま持ち込んでおり、モデル固有の劣化要因を拾えない。","opt":["正解。コード変更トリガーとは別に、データ到着や精度劣化検知などモデル固有の条件もトリガーに加える。","コード変更が無くてもデータ分布の変化などでモデルは劣化しうるため、コード変更トリガーだけでは検知できない。","運用状況や新しいリスクに応じてトリガー条件を見直す余地を残しておく方が実態に即している。","劣化検知を目視のみに頼ると発見が遅れる。パイプラインのトリガーに組み込むことで対応を早められる。"]}'),

  ('gcp-pcde-g-q53', 'オブザーバビリティの実践',
   'オブザーバビリティ運用でGemini Cloud Assistを活用できる場面として適切なものを2つ選べ。',
   NULL::text,
   '["Logs Explorer上で自然言語による問いかけから、エラーの原因についての仮説を提示させる。","分散トレースのウォーターフォールについて自然言語で問いかけ、遅延の主要因となっているスパンを絞り込む。","本番環境のインシデント対応において、ロールバックの実行そのものを承認なしにAIへ任せる。","SLOの達成状況にかかわらず、アラートポリシーの閾値をAIが自動で書き換える設定にする。"]',
   0, '[0,1]', 'multi',
   '{"asked":"Gemini Cloud Assistの実際の活用場面(ログ分析・トレース分析)を、権限を伴う自動実行と区別できるか。","why_asked":"試験ガイドはログ分析・メトリクス解釈・トレース分析へのGemini Cloud Assist活用を明記する一方、ロールバックの実行や本番設定の自動変更をAIに委ねるとは書いていない。試験は『分析支援』と『実行権限の委譲』を混同させる誤答を置き、AIの役割が助言・仮説提示にとどまることを測る。","kid":"AIはログやトレースを読んで仮説を出す係。ロールバックや設定変更を勝手にやる係ではない。","terms":[["Gemini Cloud Assist","Console上で自然言語による質問に答え、分析を支援するAI機能。"]],"think":"Gemini Cloud Assistが担うのは情報の整理と仮説提示であり、本番環境への実行操作や自動的な設定変更は別の話。『分析支援か、実行権限の委譲か』を軸に見分ける。","vs":"1番目と2番目はどちらも分析・絞り込みの支援であり適切。3番目と4番目は実行や設定変更をAIへ委ねる話であり、ガイドが示すAI活用の範囲を超えている。","opt":["正解。自然言語での問いかけからログの原因仮説を提示させるのは、明記されたログ分析支援の使い方。","正解。トレースのウォーターフォールから遅延の主要因スパンを絞り込ませるのは、明記されたトレース分析支援の使い方。","ロールバックの実行は本番環境への操作であり、承認なしにAIへ任せる運用としては明記されていない。","アラート閾値の自動書き換えは本番設定の変更であり、SLOとの整合を無視した自動化は意図しない挙動を招く。"]}'),

  ('gcp-pcde-g-q54', 'パフォーマンス最適化とトラブルシューティング',
   'Active Assistの推奨事項に従ってアイドル状態のリソースを削除し、コストを削減した。この対応を今後どう位置づけるべきか。',
   NULL::text,
   '["一度の対応で終わらせず、使用状況の変化に応じて継続的に生成される新しい推奨事項を定期的に確認し続ける運用にする。","推奨事項は一度確認して対応すれば十分であり、以後は新しい推奨事項が生成されないため確認作業自体が不要になる。","コスト削減の効果が出た以上、以後のリソース利用状況の監視自体をやめてよいと判断する。","アイドル状態のリソースは今後発生しない前提で、リソースの削除確認プロセスを恒久的に省略する。"]',
   0, '[0]', 'single',
   '{"asked":"Active Assistの推奨事項が継続的に生成される仕組みであることを理解しているか。","why_asked":"試験ガイドはパフォーマンス・コストの推奨事項を継続的な運用の一部として位置づけている。試験は『一度対応すれば終わり』という一過性の対応で満足する誤答を置き、使用状況は変化し続けるため推奨事項の確認も継続的に必要であることを測る。","kid":"一度きれいにして終わりではなく、これからも定期的にAIの提案を見に行く。","terms":[["Active Assist","使用状況を継続的に分析し、推奨事項を提示し続けるGoogle Cloudの機能群。"]],"think":"使用状況は日々変化するため、ある時点でリソースが最適化されていても、時間が経てば新たな無駄が生まれうる。だから一度きりの対応ではなく、継続的に推奨事項を確認する運用にする。","vs":"『以後は不要』『監視自体をやめる』『恒久的に省略する』はいずれも使用状況が変化し続けるという前提を無視している。","opt":["正解。使用状況の変化に応じて継続的に生成される推奨事項を、定期的に確認し続ける。","使用状況が変化する限り新しい推奨事項は生成され続けるため、確認作業が不要になるわけではない。","監視をやめると、新たに発生した無駄なリソースに気づけなくなる。","アイドル状態のリソースは運用が続く限り再び発生しうるため、確認プロセスを恒久的に省略するのは危うい。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name
 AND s.slug = split_part(v.source_ref, '-q', 1)
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
